function CashPopPanel:Awake()
    local gray = CfUtils.GetOrAddComponent(self.BtnOk.transform.parent, UIGrayGraphics)
    if gray then
        gray:MarkGray(not self.canOK)
    end
    UIEventProxy.Create(self.BtnOk.gameObject).onPointerClick = function()
        if not self.canOK then return end
        if self.confirmCB ~= nil and type(self.confirmCB) == 'function' then
            if not isNull(self.confirmCB) then
                KTool.SafeDelete(self.controller.gameObject)
                self.confirmCB()
            end
        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end

    UIEventProxy.Create(self.BtnCancel.gameObject).onPointerClick = function()
        if self.cancelCB ~= nil and type(self.cancelCB) == 'function' then
            if not isNull(self.cancelCB) then
                KTool.SafeDelete(self.controller.gameObject)
                self.cancelCB()
            end
        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end

    UIEventProxy.Create(self.btnClose.gameObject).onPointerClick = function()
        if self.isBgClose then
            if self.cancelCB ~= nil and type(self.cancelCB) == 'function' then
                if not isNull(self.cancelCB) then
                    KTool.SafeDelete(self.controller.gameObject)
                    self.cancelCB()
                end
            else
                KTool.SafeDelete(self.controller.gameObject)
            end
        end
    end
    if not isNull(self.CanvasScaler) then
        KTool.CalculateScreenFit(self.CanvasScaler)
    end

end

function CashPopPanel:OnEnable()
    self.controller:StartCoroutine(util.cs_generator(function()
        xTry(function()
            while not self.canOK do
                coroutine.yield(CoYield(1))
                self.maxTime = self.maxTime - 1
                if self.maxTime > 0 then
                    CfUtils.FillText(self.OkTxt, localize('确认(_num_)', {_num_ = self.maxTime}))
                else
                    self.canOK = true
                    CfUtils.FillText(self.OkTxt, localize('确认'))
                    local gray = CfUtils.GetOrAddComponent(self.BtnOk.transform.parent, UIGrayGraphics)
                    if gray then
                        gray:MarkGray(not self.canOK)
                    end
                end
            end
        end)
    end))
end
