    KTool.GetOrAddComponent(flagIconCancel.gameObject, typeof(ImageAlterable)):LoadSprite(string.format('uiatlas/common/%s.png', t[2].icon))
    ]]
    local t = IconImagePath[string.format('GROUP_%d', type)]
    self.OkTxt.text = t[1].name
    self.CancelTxt.text = t[2].name

    self.confirmCB = okCB
    self.cancelCB = cancelCB

    --
    self.Description.text = checkString(textTip)
    if not string.isEmpty(subTitle) then
        KTool.SetActive(self.SubTitle.gameObject, true)
        self.SubTitle.text = subTitle
    end

    if not string.isEmpty(SubText2) then
        KTool.SetActive(self.SubTitle2.gameObject, true)
        self.SubTitle2.text = SubText2
